{"path":"/root/solve.py","content":"import json, csv, pathlib, math

ROOT = pathlib.Path('/root')

manifest = json.loads((ROOT / 'campaign_manifest.json').read_text())


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


crate_rows = load_csv('crate_cost.csv')
billing_rows = load_csv('billing.csv')
location_rows = load_csv('location_overrides.csv')
suspension_rows = load_csv('suspensions.csv')


def iter_campaigns(manifest_obj):
    if isinstance(manifest_obj, list):
        for item in manifest_obj:
            yield item
    elif isinstance(manifest_obj, dict):
        if 'regions' in manifest_obj:
            for region in manifest_obj['regions']:
                for campaign in region.get('campaigns', []):
                    yield campaign
        else:
            for key, value in manifest_obj.items():
                if isinstance(value, dict):
                    campaign = dict(value)
                    campaign.setdefault('campaign_id', key)
                    yield campaign
                elif isinstance(value, list):
                    for campaign in value:
                        yield campaign
    else:
        raise TypeError('Unsupported manifest structure')


def currency(value):
    return round(float(value), 2)


crate_cost_by_tier = {
    row['crate_tier']: float(row['crate_cost_usd'])
    for row in crate_rows
}

hold_campaign_ids = {
    row['campaign_id']
    for row in suspension_rows
    if row.get('suspension_status') == 'hold'
}

DISPATCHES_6 = 60
DISPATCHES_12 = 30
DAYS_6 = 6
DAYS_12 = 12
SWITCH_THRESHOLD = 11000

campaign_outputs = []

for campaign in iter_campaigns(manifest):
    campaign_id = campaign['campaign_id']
    if campaign.get('analysis_flag') != 'review':
        continue
    if campaign_id in hold_campaign_ids:
        continue

    labels = {campaign['campaign_name']}
    labels.update(campaign.get('alias_labels') or [])
    active_billing_matches = [
        row for row in billing_rows
        if row.get('status') == 'active' and row.get('campaign_label') in labels
    ]
    if not active_billing_matches:
        raise ValueError(f'No active billing row found for {campaign_id}')
    billing = max(active_billing_matches, key=lambda row: row.get('cycle_tag', ''))
    payment = float(billing['payment_per_dispatch_per_clinic_usd'])

    qualifying_overrides = []
    for row in location_rows:
        if row.get('campaign_id') != campaign_id:
            continue
        if row.get('state') != 'approved':
            continue
        revision = (row.get('revision') or '').strip()
        active_clinics_value = (row.get('active_clinics') or '').strip()
        if not revision or not active_clinics_value:
            continue
        try:
            numeric_revision = float(revision)
            active_clinics_candidate = int(active_clinics_value)
        except ValueError:
            continue
        qualifying_overrides.append((numeric_revision, active_clinics_candidate))

    if qualifying_overrides:
        active_clinics = max(qualifying_overrides, key=lambda item: item[0])[1]
    else:
        active_clinics = int(campaign['default_active_clinics'])

    crate_tier = campaign['crate_tier']
    crate_cost = float(crate_cost_by_tier[crate_tier])
    drug_cost = float(campaign['drug_cost_per_1000_doses_usd'])
    doses_per_day = float(campaign['doses_per_day'])

    def model(dispatches_per_year, days_per_dispatch):
        annual_revenue = payment * active_clinics * dispatches_per_year
        annual_drug_cost = drug_cost * active_clinics * doses_per_day * days_per_dispatch * dispatches_per_year / 1000
        annual_crate_cost = crate_cost * dispatches_per_year
        annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost
        return {
            'revenue': currency(annual_revenue),
            'drug_cost': currency(annual_drug_cost),
            'crate_cost': currency(annual_crate_cost),
            'margin': currency(annual_margin),
        }

    six_day = model(DISPATCHES_6, DAYS_6)
    twelve_day = model(DISPATCHES_12, DAYS_12)
    margin_diff = currency(twelve_day['margin'] - six_day['margin'])

    campaign_outputs.append({
        'campaign_id': campaign_id,
        'campaign_name': campaign['campaign_name'],
        'active_clinics': active_clinics,
        'drug_cost_per_1000_doses_usd': currency(drug_cost),
        'doses_per_day': int(doses_per_day) if doses_per_day.is_integer() else doses_per_day,
        'crate_tier': crate_tier,
        'crate_cost_usd': currency(crate_cost),
        'payment_per_dispatch_per_clinic_usd': currency(payment),
        'annual_drug_cost_6_day_usd': six_day['drug_cost'],
        'annual_drug_cost_12_day_usd': twelve_day['drug_cost'],
        'annual_crate_cost_6_day_usd': six_day['crate_cost'],
        'annual_crate_cost_12_day_usd': twelve_day['crate_cost'],
        'annual_revenue_6_day_usd': six_day['revenue'],
        'annual_revenue_12_day_usd': twelve_day['revenue'],
        'annual_margin_6_day_usd': six_day['margin'],
        'annual_margin_12_day_usd': twelve_day['margin'],
        'annual_margin_difference_12_minus_6_usd': margin_diff,
    })

campaign_outputs.sort(key=lambda item: item['campaign_id'])

total_margin_6 = currency(sum(item['annual_margin_6_day_usd'] for item in campaign_outputs))
total_margin_12 = currency(sum(item['annual_margin_12_day_usd'] for item in campaign_outputs))
total_diff = currency(total_margin_12 - total_margin_6)
abs_diff = currency(abs(total_diff))
decision = 'move_to_12_day' if abs_diff < SWITCH_THRESHOLD else 'keep_6_day'

output = {
    'assumptions': {
        'dispatches_per_year_6_day': DISPATCHES_6,
        'dispatches_per_year_12_day': DISPATCHES_12,
        'days_per_dispatch_6_day': DAYS_6,
        'days_per_dispatch_12_day': DAYS_12,
        'switch_threshold_usd': SWITCH_THRESHOLD,
        'override_rule': 'highest numeric approved revision with non-empty active_clinics, else default_active_clinics',
        'suspension_rule': 'exclude hold campaigns',
    },
    'campaigns': campaign_outputs,
    'totals': {
        'total_annual_margin_6_day_usd': total_margin_6,
        'total_annual_margin_12_day_usd': total_margin_12,
        'total_annual_margin_difference_12_minus_6_usd': total_diff,
        'absolute_total_margin_difference_usd': abs_diff,
    },
    'recommendation': {
        'decision': decision,
        'justification': f'Absolute annual margin difference is ${abs_diff:,.2f}, compared with the ${SWITCH_THRESHOLD:,.2f} switch threshold; decision: {decision}.',
    },
}

(ROOT / 'vaxcrate_analysis.json').write_text(json.dumps(output, indent=2) + '\n')

summary_lines = [
    '# Vaxcrate dispatch cadence analysis',
    f'Total 6-day margin (USD): ${total_margin_6:,.2f}',
    f'Total 12-day margin (USD): ${total_margin_12:,.2f}',
    f'Absolute difference (USD): ${abs_diff:,.2f}',
    f'Decision: {decision}',
]
(ROOT / 'vaxcrate_summary.md').write_text('\n'.join(summary_lines) + '\n')
